import os
for root,ds,fs in os.walk('studies'):
 for f in fs: print(root,f)

import gzip,glob
for p in sorted(glob.glob('studies/data/raw/*matrix*')):
 print('\nFILE',p)
 with gzip.open(p,'rt') as f:
  for l in f:
   if l.startswith(('!Series_title','!Series_summary','!Series_overall_design','!Sample_geo_accession','!Sample_title','!Sample_source_name','!Sample_characteristics','!Sample_treatment_protocol')): print(l.strip())

import gzip,glob,csv
for p in sorted(glob.glob('studies/data/raw/*matrix*'))[2:]:
 print('\nFILE',p)
 rows=[r for r in csv.reader(gzip.open(p,'rt'),delimiter='\t') if r and r[0].startswith('!')]
 for r in rows:
  if r[0].startswith('!Series_') and r[0] in ['!Series_title','!Series_overall_design','!Series_summary']: print(r)
 keys=['!Sample_geo_accession','!Sample_title','!Sample_characteristics_ch1','!Sample_source_name_ch1']
 sel=[r for r in rows if r[0] in keys]
 for i in range(1,len(sel[0])): print(' | '.join(r[i] for r in sel))
 for key in ['!Sample_treatment_protocol_ch1','!Sample_growth_protocol_ch1','!Sample_description']:
  print(key)
  for r in rows:
   if r[0]==key: print('\n'.join(dict.fromkeys(r[1:])))

